export function ArrangementVideoDock() {
  const { arrangement, position, isPlaying, videoSources, pausePlaybackWithStatus } =
    useArrangement();
  const videoRef = useRef<HTMLVideoElement>(null);
  const seekControllerRef = useRef<AbortController | null>(null);
  const lastHardSeekRef = useRef(Number.NEGATIVE_INFINITY);
  const lastPositionRef = useRef(position);
  const playPendingRef = useRef(false);
  const isPlayingRef = useRef(isPlaying);
  isPlayingRef.current = isPlaying;

  const videoTrackId = arrangement.tracks.find((track) => track.kind === 'video')?.id;
  const hasVideoClips = arrangement.clips.some((clip) => clip.trackId === videoTrackId);
  const location = findVideoClipAt(arrangement, position);
  const source = location ? videoSources.get(location.clip.sourceId) : undefined;
  const activeUrl = source?.url ?? null;
  const mediaTime = location?.mediaTime ?? 0;

  useEffect(() => {
    const video = videoRef.current;
    if (!video) {
      return;
    }
    video.muted = true;
    const advanced = position > lastPositionRef.current;
    lastPositionRef.current = position;
    if (!activeUrl) {
      seekControllerRef.current?.abort();
      video.pause();
      return;
    }
    let sourceChanged = false;
    if (video.getAttribute('src') !== activeUrl) {
      video.src = activeUrl;
      sourceChanged = true;
    }
    if (!isPlaying) {
      video.pause();
      seekControllerRef.current?.abort();
      const controller = new AbortController();
      seekControllerRef.current = controller;
      seekSfxVideo(video, mediaTime, controller.signal).catch(() => undefined);
      return;
    }
    seekControllerRef.current?.abort();
    const now = performance.now();
    const drifted =
      videoDriftAction(video.currentTime, mediaTime, true) === 'seek' &&
      now - lastHardSeekRef.current >= HARD_SEEK_INTERVAL_MS;
    if (sourceChanged || drifted) {
      video.currentTime = mediaTime;
      lastHardSeekRef.current = now;
    }
    if (video.paused && advanced && !playPendingRef.current) {
      playPendingRef.current = true;
      video.play().then(
        () => {
          playPendingRef.current = false;
          if (!isPlayingRef.current) {
            video.pause();
          }
        },
        (error: unknown) => {
          playPendingRef.current = false;
          if (error instanceof DOMException && error.name === 'AbortError') {
            return;
          }
          if (isPlayingRef.current) {
            pausePlaybackWithStatus(VIDEO_PLAY_FAILED_MESSAGE);
          }
        },
      );
    }
  }, [activeUrl, mediaTime, isPlaying, position, pausePlaybackWithStatus]);

  useEffect(() => {
    return () => {
      seekControllerRef.current?.abort();
    };
  }, []);

  return (
    <section
      aria-label="ßâòßâÿßâôßâößâ¥"
      className="shrink-0 border-t border-r border-outline bg-surface p-2"
      data-testid="arrangement-video-dock"
    >
      <p className="mb-1 truncate text-xs text-muted">
        {source ? source.name : 'ßâòßâÿßâôßâößâ¥'}{' '}
        <span className="text-dim">┬╖ ßâ«ßâ¢ßâÉ ßâòßâÿßâôßâößâ¥ßâ«ßâÉßâûßâÿßâôßâÉßâ£ (M/S/Volume)</span>
      </p>
      <div className="relative aspect-video w-full overflow-hidden rounded-sm bg-background">
        <video
          ref={videoRef}
          muted
          playsInline
          preload="auto"
          className={cn('h-full w-full object-contain', !activeUrl && 'hidden')}
          data-testid="arrangement-video"
        />
        {hasVideoClips ? null : (
          <p className="absolute inset-0 flex items-center justify-center p-2 text-center text-xs text-muted">
            ßâòßâÿßâôßâößâ¥ ßâ»ßâößâá ßâÉßâá ßâôßâÉßâÆßâÿßâ¢ßâÉßâóßâößâæßâÿßâÉ
          </p>
        )}
        {hasVideoClips && !activeUrl ? (
          <p
            className="absolute inset-0 flex items-center justify-center p-2 text-center text-xs tabular-nums text-muted"
            data-testid="arrangement-video-gap"
          >
            ßâòßâÿßâôßâößâ¥ ßâÉßâá ßâÉßâáßâÿßâí ┬╖ {formatArrangementTime(position)}
          </p>
        ) : null}
      </div>
    </section>
  );
}
